CREATE TABLE generations(id TEXT PRIMARY KEY, bot_id INTEGER NOT NULL, expected INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'staging');
CREATE TABLE folders(generation TEXT NOT NULL, id TEXT NOT NULL, title TEXT NOT NULL, rank INTEGER NOT NULL, ordinal INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(generation,id));
CREATE INDEX folders_order ON folders(generation,rank DESC,ordinal);
CREATE TABLE config(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE favorites(owner INTEGER NOT NULL,job TEXT NOT NULL,PRIMARY KEY(owner,job));
CREATE TABLE subscribers(owner INTEGER PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE events(id TEXT PRIMARY KEY, type TEXT NOT NULL, owner INTEGER NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', next_at INTEGER NOT NULL DEFAULT 0, touched INTEGER NOT NULL, error TEXT NOT NULL DEFAULT '');
CREATE INDEX events_pending ON events(state,next_at);
CREATE TABLE sends(id TEXT PRIMARY KEY,state TEXT NOT NULL,response TEXT,error TEXT NOT NULL DEFAULT '');
CREATE TABLE panels(chat INTEGER NOT NULL,message INTEGER NOT NULL,stats INTEGER,PRIMARY KEY(chat,message));
CREATE TABLE cards(chat INTEGER NOT NULL,message INTEGER NOT NULL,job TEXT NOT NULL,PRIMARY KEY(chat,message));
CREATE TABLE views(chat INTEGER NOT NULL,origin INTEGER NOT NULL,event TEXT NOT NULL,PRIMARY KEY(chat,origin));
CREATE TABLE importer_inbox(id INTEGER PRIMARY KEY,payload TEXT NOT NULL,expires INTEGER NOT NULL,lease INTEGER NOT NULL DEFAULT 0);
CREATE TABLE notice_seen(job TEXT PRIMARY KEY);
